def solution(input_str):
    n, *a = map(int, input_str.split())

    total = sum(a)

    # If total sum is 1, we can't find any k > 1
    if total <= 1:
        return "-1"
    # If only one box and already divisible by some k>1, cost is 0
    if n == 1:
        if total == 0:
            return "0"
        # For single box, it's already satisfied for k=total (if total>1)
        # But if total=1, we can't satisfy, handled above
        return "0"

    def get_cost(k):
        """Calculate minimum moves to make all divisible by k"""
        cost = 0
        current_chunk = 0
        for x in a:
            current_chunk += x
            cost += current_chunk // k
            current_chunk %= k
        return cost

    # Find all divisors of total
    ans = float('inf')

    for i in range(2, int(total**0.5) + 1):
        if total % i == 0:
            ans = min(ans, get_cost(i))
            if i != total // i:
                ans = min(ans, get_cost(total // i))

    # Check total itself
    ans = min(ans, get_cost(total))

    return str(ans)

