            l, r = int(parts[0]), int(parts[1])
            offers.append((l, r))

    results = []

    for x in range(1, n + 1):
        occupied = [False] * (n + 2)
        total_days = 0

        for l, r in offers:
            length = r - l + 1
            if length >= x:
                can_accept = True
                for day in range(l, r + 1):
                    if occupied[day]:
