from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '-1'

    first_line = lines[0].split()
    n, m, k = int(first_line[0]), int(first_line[1]), int(first_line[2])

    edges = []
    adj = [[] for _ in range(n + 1)]

    for i in range(1, m + 1):
        line = lines[i].split()
        u, v = int(line[0]), int(line[1])
        adj[u].append(v)
        adj[v].append(u)
        edges.append((u, v))

    # Strategy: Try to find k cycles first
    # Each cycle needs length >= 3 and not divisible by 3
    # Each cycle needs a unique representative vertex

    # We'll use DFS to find cycles
    # For each cycle, pick a vertex that hasn't been used as representative elsewhere

    cycles = []
    used_representatives = set()

    # Function to try finding cycles
    def find_cycles(start_node, visited_edges, path, path_set):
        nonlocal cycles
        # Try to find cycles of different lengths
        if len(path) >= 2:  # Need at least 2 edges for a cycle
            for nxt in adj[path[-1]]:
                if nxt in path_set:
                    # Found a cycle
                    cycle_path = path[path.index(nxt) + 1:] + [nxt]
                    cycle_len = len(path[path.index(nxt) + 1:])
                    if cycle_len >= 3 and cycle_len % 3 != 0:
                        # Need to find a representative
                        # Pick a vertex that's not in any other cycle's representatives
                        rep_found = False
                        rep_node = -1
                        for node in cycle_path[:-1]:  # Exclude last (same as first)
                            if node not in used_representatives:
                                rep_found = True
                                rep_node = node
                                break
                        if rep_found:
                            cycles.append((cycle_path[:-1], rep_node))
                            used_representatives.add(rep_node)
        else:
            for nxt in adj[path[-1]]:
                if nxt not in visited_edges and nxt not in path_set:
                    visit = (path[-1], nxt)
                    if visit in visited_edges:
                        continue
                    visited_edges.add(visit)
                    path.append(nxt)
                    path_set.add(nxt)
                    find_cycles(start_node, visited_edges, path, path_set)
                    path.pop()
                    path_set.remove(nxt)
                    visited_edges.discard((path[-1], nxt))

    # Alternative: Try BFS for path finding
    def find_long_path(start):
        visited = {start}
        queue = deque([(start, [start])])
        while queue:
            node, path = queue.popleft()
            if len(path) >= n // k + 1:
                return path
            for nxt in adj[node]:
                if nxt not in visited:
                    visited.add(nxt)
                    queue.append((nxt, path + [nxt]))
        return None

    # First try to find k cycles
    nodes_to_remove = [None] * k
    for i in range(k):
        found = False
        for start in range(1, n + 1):
            if used_representatives and start in used_representatives:
                continue
            # Try to find a triangle or longer cycle
            path = [start]
            found_cycle = False
            seen_edges = set()

            # Look for cycles of length 4, 5, 7, etc (not divisible by 3)
            for depth in range(3, 15):
                if found_cycle and len(cycles) >= k:
                    break

                visited_df = {start}
                visited_edges_local = []  # Track edges

                # Simple DFS with limit
                stack = [(start, [-1, -1], [start])]  # node, parent, path
                while stack and depth > 0:
                    curr, par, pat = stack.pop()
                    pat = pat + [curr]
                    for next_node in adj[curr]:
                        if next_node == par:
                            continue
                        if next_node in pat:
                            # Found cycle
                            idx = pat.index(next_node)
                            cycle_pat = pat[idx:]
                            cycle_len = len(cycle_pat)
                            if cycle_len >= 3 and cycle_len % 3 != 0:
                                # Find representative
                                rep = cycle_pat[0]
                                if rep not in used_representatives:
                                    cycles.append((cycle_pat, rep))
                                    used_representatives.add(rep)
                                    found_cycle = True
                                    break
                        elif len(pat) < 10:
                            stack.append((next_node, curr, pat))

                if found_cycle:
                    break

            if found_cycle:
                break

    if len(cycles) >= k:
        # Output cycles
        result = ['CYCLES']
        for cycle_path, rep in cycles[:k]:
            result.append(str(len(cycle_path)))
            result.append(' '.join(map(str, cycle_path)))
        return '\n'.join(result)

    # If not enough cycles, try to find long path
    for start in range(1, n + 1):
        path = find_long_path(start)
        if path and len(path) >= n // k + 1:
            result = ['PATH']
            result.append(str(len(path)))
            result.append(' '.join(map(str, path)))
            return '\n'.join(result)

    return '-1'

def can_solve(arr):
    """Check if we can remove all stones from the piles."""
    if not arr:
        return False
    if len(arr) == 1:
        return arr[0] == 0

    # Process from left to right
    needed = 0  # stones that need to be sent to the current pile from the right
    for x in reversed(arr):
        if needed > 0 and x > needed:
            # Has more than needed, excess must be sent to left
            needed -= x
        else:
            # Not enough or exactly right
            if x < needed:
                return False
        needed -= x

    return needed == 0


def can_remove_all(stones):
    """Greedy approach: check from left to right if we can clear all piles."""
    balance = 0
    for x in stones:
        balance += x
        if balance < 0:
            return False
        balance -= x
    return balance == 0


def solution(input_str):
    input_lines = input_str.strip().split('\n')
    idx = 0

    t = int(input_lines[idx])
    idx += 1

    results = []

    for _ in range(t):
        n = int(input_lines[idx])
        idx += 1
        a = list(map(int, input_lines[idx].split()))
        idx += 1

        # First check if original arrangement works
        if can_remove_all(a):
            results.append("YES")
            continue

        # Check with all adjacent swaps
        possible = False
        for i in range(n - 1):
            # Make a copy and swap adjacent elements
            arr = a[:]
            arr[i], arr[i + 1] = arr[i + 1], arr[i]
            if can_remove_all(arr):
                possible = True
                break

        if possible:
            results.append("YES")
        else:
            results.append("NO")

    return '\n'.join(results)


