    fixed_has_k = False
    curr = 0
    for c in s:
        if c == 'N':
            curr += 1
            if curr == k:
                fixed_has_k = True
        elif c != '?':
            curr = 0

    if fixed_has_k:
        return 'YES\n'

    # Check if we can create a block of k using '?'
    # We need at least k consecutive positions that are not fixed 'Y'

    positions = []
