        if not points or len(R) == 4:
            return empty_sphere(R)

        p = points.pop(0)
        S = welzl(points, R)
        points.insert(0, p)

        if not inside_sphere(p, S):
            return welzl(points, R + [p])

    def inside_sphere(p, s):
        center, rsq = s
        if rsq == 0:
            return True
        return distance_sq(p, center) <= rsq + 1e-10

    def empty_sphere(R):
        return [0.0, 0.0, 0.0, float('inf')]

    # Simple solution: compute convex hull centers and distances
    cx, cy, cz = 0.0, 0.0, 0.0
    max_dist = 0.0
    for i in range(len(points)):
        d = distance_sq(points[i], points[i])
        if d > max_dist:
            max_dist = d

    return f"{cx:.10f} {cy:.10f} {cz:.10f}"

