def resulting_val(integer_part, fractional, a):
    val = integer_part * a
    for _ in range(a):
        val += 1 if fractional != 0 else 0
    return min(val, float('inf'))

def resulting_mul(k, x, a):
    for _ in range(a):
        k = math.ceil(k * x)
        if k > 100000000:
            return None
    return k

