import math
from collections import defaultdict

def get_divisors(n):
    """Get all divisors of n greater than 1"""
    divs = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i > 1:
                divs.add(i)
            d2 = n // i
            if d2 > 1 and d2 != i:
                divs.add(d2)
    return sorted(divs)

def get_prime_factors(n):
    """Get unique prime factors of n"""
    factors = set()
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return sorted(factors)

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def get_primes_up_to_sqrt(n):
    """Get prime numbers up to sqrt(n)"""
    primes = []
    i = 2
    while i * i <= n:
        is_prime = True
        for p in primes:
            if p * p > i:
                break
            if i % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(i)
        i += 1
    return primes

def get_prime_divs(n):
    """For each prime factor, find divisors divisible by it"""
