            current_y %= g
            if current_y < g:
                current_y += g
            if current_y > 0:
                continue

        ans = current_y // g
        if g == current_a // gcd(current_a, current_a // g):
            ans += 1

        count += ans
        current_y -= ans * g
        gcd_changed = False

