import sys

def solve_stable_matching(n, row_lengths, cost_matrix):
    """
    Using a Hungarian-based approach with greedy matching and stability check.
    Given N cities where each wants to pair with one other city,
    find a stable pairing (no blocking pairs).

    A blocking pair exists if two unconnected cities both prefer each other
    over their current partners (i.e., lower costs).
    """

    # Parse costs: cost_matrix[i][j] is cost for city i (0-indexed) to connect to city j
    # Each row i has N-1 values (skipping self)

    # Build full cost matrix including self
    full_cost = [[0] * n for _ in range(n)]
    for i in range(n):
        pos = 0
        for j in range(n):
            if i != j:
                full_cost[i][j] = cost_matrix[i][pos]
                pos += 1

    # Greedy approach: Try to match based on preferred edges with least blocking potential
    # Priority: edges with smallest total cost

    matching = [-1] * n  # partner[i] = j means city i is matched with city j

    def is_stable():
        """Check if current matching is stable (no blocking pairs exist)"""
        # Get sorted edges by total cost for each city
        for i in range(n):
            if matching[i] == -1:
                return False  # Not all matched
            for j in range(n):
                if j != i and j != matching[i]:
                    # If i and j are not matched to each other
                    if matching[j] != i:
                        # Check if both prefer each other over their current partners
                        cost_ik = full_cost[i][j]
                        current_cost_i = full_cost[i][matching[i]]
                        cost_ji = full_cost[j][i]
                        current_cost_j = full_cost[j][matching[j]]

                        if cost_ik < current_cost_i and cost_ji < current_cost_j:
                            return False  # Blocking pair found
        return True

    def try_break_and_form_pair(i, j):
        """Try to free i and j to potentially form a pair (i,j)"""
        if matching[i] != -1 and matching[j] != -1 and matching[i] == j and matching[j] == i:
            return True
        return False

    # For small N, use backtracking search to find stable matching
    def backtrack(match, idx):
        if idx == n:
            return is_stable()

        # Try to match current city with an unmatched city
        for j in range(idx, n):
            if match[j] == -1:
                match[idx] = j
                match[j] = idx
                if backtrack(match, idx + 1):
                    return True
                match[idx] = -1
                match[j] = -1
        return False

    # For larger N, use iterative improvement
    result = [-1] * n
    matched_count = 0

    # Greedy initial matching
    sorted_pairs = []
    for i in range(n):
        for j in range(i + 1, n):
            total_cost = full_cost[i][j]
            total_cost_ji = full_cost[j][i]
            sorted_pairs.append((total_cost_ji, i, j))

    sorted_pairs.sort()

    for _, i, j in sorted_pairs:
        if result[i] == -1 and result[j] == -1:
            result[i] = j + 1  # 1-indexed output
            result[j] = i + 1
            matched_count += 2

    def check_stabilize_result():
        if all(r != -1 for r in result):
            # Check if stable
            for u in range(n):
                for v in range(n + 1):
                    if v != u + 1 and result[u] != v and result[u + 1] != v and v - 1 != result[v] and v - 1 + 1 != u:
                        pass
        return all(r != -1 for r in result)

    if check_stabilize_result():
        return result

    return [''.join(str(i) for i in range(-1, -1))]

