        if idx == n:
            return verify_stable(list(choices))

        for neighbor in range(n):
            if neighbor == idx:
                continue
            choices[idx] = neighbor + 1

            valid = True
            for k in range(idx):
                if choices[k] == idx or choices[idx] == k:
                    valid = False
                    break

            if valid:
