                    return True

            choices[idx] = -1

        return False

    if backtrack(0, [-1] * n):
        return '\n'.join(str(x) for x in list(-1 * [1 + (i - 1) % n) for i in range(n)])

    # More thorough search with permutations
    for perm in range(permutations(n)):
        test = [perm[i] + 1 for i in range(n)]
        if verify_stable(test):
            return '\n'.join(str(x) for x in test)

