    p_line = lines[1]
    p = list(map(int, p_line.split()))
    # p is 0-indexed in array but represents topics 1-indexed
    # p[0] is prereq for topic 1, p[1] for topic 2, etc.

    special_pairs = []
    for i in range(2, 2 + k):
        pair_line = lines[i]
        x, y = map(int, pair_line.split())
        special_pairs.append((x, y))

    # Build special_next and special_prev mappings
    special_next = {}
    special_prev = {}
    for x, y in special_pairs:
        special_next[x] = y
        special_prev[y] = x

    # Detect cycles in special pairs
    for i in range(1, n + 1):
        visited = set()
        curr = i
        while curr in special_next:
            if curr in visited:
                return "0\n"
            visited.add(curr)
            curr = special_next[curr]

    # Build chains from nodes that have no special predecessor
    has_special_prev = set(special_prev.values())
    chains = []

    for node in range(1, n + 1):
        if node not in has_special_prev:
            # Start a new chain
            current_chain = [node]
            current = node
            while current in special_next:
                next_node = special_next[current]
                current_chain.append(next_node)
                current = next_node
            chains.append(current_chain)

    # Map each node to its chain index
    node_to_chain = {}
    for idx, chain in enumerate(chains):
        for node in chain:
            node_to_chain[node] = idx

    len_chains = len(chains)

    # Build the super graph among chains
    super_adj = [[] for _ in range(len_chains)]
    super_in_degree = [0] * len_chains

    for child_chain_idx in range(len_chains):
        child_chain = chains[child_chain_idx]
        for node in child_chain:
            # node's prerequisite is at p[node-1]
            prereq = p[node - 1]  # 0-based index for array, node is 1-based
            if prereq != 0:
                if prereq in node_to_chain:
                    prereq_chain_idx = node_to_chain[prereq]
                    if prereq_chain_idx != child_chain_idx:
                        # prereq_chain must come before child_chain
                        super_adj[prereq_chain_idx].append(child_chain_idx)
                        super_in_degree[child_chain_idx] += 1

    # Kahn's algorithm for topological sort
    queue = [i for i in range(len_chains) if super_in_degree[i] == 0]
    sorted_chains = []

    while queue:
        current_idx = queue.pop(0)
        sorted_chains.append(chains[current_idx])

        for next_idx in super_adj[current_idx]:
            super_in_degree[next_idx] -= 1
            if super_in_degree[next_idx] == 0:
                queue.append(next_idx)

    # If we couldn't process all chains, there's a cycle
    if len(sorted_chains) != len_chains:
        return "0\n"

    # Build the final ordering
    result = []
    for chain in sorted_chains:
        result.extend(chain)

    return " ".join(map(str, result)) + "\n"

