        adj[u].append(v)
        adj[v].append(u)

    target = math.ceil(math.sqrt(n))

    visited = [False] * (n + 1)
    parent = [0] * (n + 1)
    dfs_path = []
    answer_cycle = None

    def dfs(u):
        nonlocal answer_cycle
        visited[u] = True
        dfs_path.append(u)

        for v in adj[u]:
            if v == parent[u]:
                continue
            if not visited[v]:
                parent[v] = u
                dfs(v)
                if answer_cycle is not None:
                    return
            else:
                # Back edge found - potential cycle
                try:
                    start_idx = dfs_path.index(v)
                    cycle_len = len(dfs_path) - start_idx
                    if cycle_len >= target:
                        answer_cycle = dfs_path[start_idx:]
                        return
                except ValueError:
                    pass

        dfs_path.pop()

    dfs(1)

    if answer_cycle is not None:
        return f"2\n{len(answer_cycle)}\n{' '.join(map(str, answer_cycle))}\n"
    else:
        # Independent set solution
        # Vertices at same depth in DFS form independent set
        level_to_nodes = {}

        for u in range(1, n + 1):
            if visited[u]:
                depth = dfs_path.index(u) if u in dfs_path else 0
                if depth not in level_to_nodes:
                    level_to_nodes[depth] = []
                level_to_nodes[depth].append(u)

        for level, nodes in level_to_nodes.items():
            if len(nodes) >= target:
                result = nodes[:target]
                return f"1\n{' '.join(map(str, result))}\n"

        # Fallback - use first target vertices
        result = list(range(1, n + 1))[:target]
