    N, M, K = map(int, lines[0].split())

    # Parse transformers: (x, y, d, t, e)
    transformers = []
    for i in range(1, 1 + K):
        parts = list(map(int, lines[i].split()))
        x, y, d, start_time, energy = parts
        transformers.append((x, y, d, start_time, energy))

    # For each cell (i,j), calculate total energy needed to kill transformers
    # that are present at this cell at time (i+j)
    cell_costs = [[0] * M for _ in range(N)]

    for x, y, d, tm, e in transformers:
        # The 4 positions in the jumping cycle
        positions = [(x, y), (x + d, y - d), (x + d, y), (x, y + d)]

        # For each position, at which time offset is it visited
        # Position 0 at time tm, Position 1 at time tm+1, etc.
        # Position k at times tm + k + 4*n for n >= 0

        for pos_idx in range(4):
            px, py = positions[pos_idx]
            time_start = tm + pos_idx

            # Find all cells (i,j) where i+j = time_start
            # i+j = tm + pos_idx means we're looking at specific diagonal
            for s_offset in range(N + M - 2 + 1):
                target_time = time_start + s_offset * 4
                if target_time > tm + N + M - 2:
                    break
                if target_time < 0:
                    continue

                # For time T, cells where i+j = T are on diagonal
                # i ranges from max(0, T-M+1) to min(T, N-1)
                start_i = max(0, target_time - M + 1)
                end_i = min(target_time, N - 1)

                for i in range(start_i, end_i + 1):
                    j = target_time - i
                    if 0 <= j < M:
                        if px == i and py == j:
                            cell_costs[i][j] += e

    # DP to find minimum energy path
    INF = float('inf')
    dp = [[INF] * M for _ in range(N)]

    # Starting point cost is any transformer at (0,0)
    dp[0][0] = cell_costs[0][0]

    # Process cells in order of time (i+j)
    for time_step in range(N + M - 1):
        for i in range(N):
            for j in range(M):
                if i + j != time_step:
                    continue
                if dp[i][j] == INF:
                    continue

                # Try moving right to (i, j+1)
                if j + 1 < M and dp[i][j] != INF:
                    new_cost = dp[i][j] + cell_costs[i][j + 1]
                    if new_cost < dp[i][j + 1]:
                        dp[i][j + 1] = new_cost

                # Try moving down to (i+1, j)
                if i + 1 < N and dp[i][j] != INF:
                    new_cost = dp[i][j] + cell_costs[i + 1][j]
                    if new_cost < dp[i + 1][j]:
                        dp[i + 1][j] = new_cost

    result = dp[N - 1][M - 1]
    return str(int(result)) + '\n' if result != INF else '0\n'

