    # mask[i] = bitmask representing vertices connected to vertex i
    adj = [0] * n
    for u, v in edges:
        adj[u] |= (1 << v)
        adj[v] |= (1 << u)

    total_ways = 1 << n
    count_valid = 0

    def check(mask):
        has_0 = False
        has_1 = False
        has_2 = False

        for u, v in edges:
            val = (mask >> u) & 1 + (mask >> v) & 1
            if val == 0:
                has_0 = True
            elif val == 1:
                has_1 = True
            elif val == 2:
                has_2 = True

        return has_0 and has_1 and has_2

    for mask in range(total_ways):
        if check(mask):
            count_valid += 1

    return f"{count_valid}\n"

