def solution(input_str):
    lines = input_str.splitlines()
    if not lines:
        return "-1"

    n, m = map(int, lines[0].split())

    # Read tables A and B
    A = []
    for i in range(1, n + 1):
        A.append(list(map(int, lines[i].strip().split())))

    B = []
    for i in range(n + 1, 2 * n + 1):
        B.append(list(map(int, lines[i].strip().split())))

    # Helper to compare two tables
    def tables_equal(t1, t2):
        if len(t1) != len(t2) or len(t1[0]) != len(t2[0]):
            return False
        for row1, row2 in zip(t1, t2):
            if row1 != row2:
                return False
        return True

    # Helper to create a hashable state key for visited set
    def state_key(t):
        return tuple(tuple(row) for row in t)

    # Verify A and B have the same rows (same multiset)
    if state_key(A) != state_key(B):
        return "-1"

    # BFS to find column sorting sequence
    visited = {state_key(A)}
    queue = deque([(A, [])])  # (table, list of column indices used)

    while queue:
        table, cols = queue.popleft()

        # Stop if we exceed the limit
        if len(cols) >= 5000:
            continue

        # Try sorting by each column
        for c in range(m):
            # Apply stable sort by column c+1 (0-indexed internally, 1-indexed in output)
            sorted_table = sorted(table, key=lambda row: row[c])
            new_key = state_key(sorted_table)

            # Check if we reached the target
            if tables_equal(sorted_table, B):
                # Convert 0-indexed columns to 1-indexed
                result_cols = [x + 1 for x in cols] + [c + 1]
                return f"{len(result_cols)}\n{' '.join(map(str, result_cols))}"

            # Add to queue if not visited
            if new_key not in visited:
                visited.add(new_key)
                queue.append((sorted_table, cols + [c]))

    # No solution found
    return "-1"

